/* Selected-output exports only. No original, memory, context or prior versions. */
(()=>{'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validDate=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));
const date=x=>validDate(x)?new Intl.DateTimeFormat('ar-SA-u-ca-gregory',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'غير محدد';
function selectExport(d,now=new Date().toISOString()){return {title:String(d?.title||'مسودة إلهامي'),kind:String(d?.kind||'مسودة'),created:validDate(d?.created)?d.created:null,updated:validDate(d?.updated)?d.updated:null,exported:validDate(now)?now:new Date().toISOString(),slides:(Array.isArray(d?.slides)?d.slides:[]).map(s=>({title:String(s.title||''),body:String(s.body||''),origin:String(s.origin||'')}))};}
const style=`*{box-sizing:border-box}html{direction:rtl}body{margin:0;background:#f6f2e9;color:#294759;font:16px/1.95 Tahoma,Arial,sans-serif}.paper{max-width:850px;margin:32px auto;background:#fffdf8;padding:48px;border-top:5px solid #5c8198;box-shadow:0 8px 40px #2947590a}.mast{display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid #dcd7ca;padding-bottom:20px}.brand{font-size:32px;font-weight:bold;color:#456b7f}.brand small{display:block;font-size:11px;font-weight:normal;letter-spacing:1px}.export-logo{display:block;width:180px;max-width:100%;height:auto;mix-blend-mode:multiply;filter:saturate(.6)}.meta{color:#637a82;font-size:11px}h1{font-size:30px;line-height:1.6;font-weight:500;margin:30px 0 12px;overflow-wrap:anywhere}h2{font-size:19px;line-height:1.7;font-weight:500;margin:0 0 10px}.section{border-right:3px solid #b5c9cd;padding:18px 22px;margin:22px 0;background:#f5f6ef}.body{white-space:pre-wrap;overflow-wrap:anywhere}.origin{font-size:11px;color:#6a7d81;border-top:1px solid #dedfd5;padding-top:10px;margin-top:16px;white-space:pre-wrap;overflow-wrap:anywhere}.number{font-size:11px;color:#8b826b}.foot{border-top:1px solid #ded9cb;margin-top:30px;padding-top:14px;color:#74848a;font-size:11px}.subtitle{color:#6c8088;font-size:13px}.document-map{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}.document-map span{border:1px solid #cbd8d4;padding:4px 12px;border-radius:20px;font-size:11px;background:#eef2eb}@media(max-width:600px){.paper{padding:22px;margin:0}.mast{gap:10px;align-items:flex-start}.brand{font-size:25px}.meta{font-size:10px}h1{font-size:25px}.section{padding:16px}}@media print{@page{size:A4;margin:16mm}body{background:white;font-size:12pt}.paper{margin:0;padding:0;max-width:none;box-shadow:none;border-top:3px solid #5c8198}.section{background:white;break-inside:auto}.section h2{break-after:avoid}.body{orphans:3;widows:3}.mast{break-after:avoid}.foot{break-inside:avoid}h1{font-size:23pt}.document-map{display:none}}`;
function mark(){return '<img class="export-logo" alt="إلهامي" src="data:image/webp;base64,">';}
function content(x){return `<article class="paper"><header class="mast"><div class="brand">${mark()}<small>حوار يبقى أثره</small></div><div class="meta">إنشاء المسودة: ${esc(date(x.created))}<br>آخر تعديل: ${esc(date(x.updated))}<br>إنشاء هذا الملف: ${esc(date(x.exported))}</div></header><p class="subtitle">${esc(x.kind)} · نسخة مشاركة من المسودة الحالية</p><h1>${esc(x.title)}</h1><div class="document-map" aria-label="أجزاء الملف">${x.slides.map((s,i)=>`<span>${i+1} · ${esc(s.title)}</span>`).join('')}</div>${x.slides.map((s,i)=>`<section class="section"><div class="number">${String(i+1).padStart(2,'0')}</div><h2>${esc(s.title)}</h2><div class="body">${esc(s.body)}</div>${s.origin?`<div class="origin">منشأ البطاقة: ${esc(s.origin)}</div>`:''}</section>`).join('')}<footer class="foot">إلهامي · هذه نسخة من الكلمات والبطاقات المختارة وقت التصدير، وليست سجل الحساب أو تحليلًا للشخصية. نسب المصادر كما دوّنت في المسودة.</footer></article>`;}
function buildHTML(x){return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><title>${esc(x.title)} — إلهامي</title><style>${style}</style></head><body>${content(x)}</body></html>`;}
function buildText(x){return ['إلهامي — حوار يبقى أثره',x.title,x.kind,'إنشاء المسودة: '+date(x.created),'إنشاء الملف: '+date(x.exported),...x.slides.map((s,i)=>`${i+1}. ${s.title}\n${s.body}\nمنشأ البطاقة: ${s.origin}`)].join('\n\n');}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function open(d,{modal,notify}){const x=selectExport(d),html=buildHTML(x),blob=new Blob([html],{type:'text/html;charset=utf-8'});modal(`<div class="export-dialog"><span class="tag">معاينة ملفك قبل المشاركة</span><h2>${esc(x.title)}</h2><p>يشمل هذا الملف عنوان المسودة الحالية وبطاقاتها الظاهرة ومنشأ كل بطاقة فقط. لا يشمل مذكراتك الخاصة أو الإصدارات السابقة. راجع الكلمات قبل إرسالها.</p><p class="small muted">لملف PDF: افتح الطباعة ثم اختر «حفظ كملف PDF» أو مشاركة PDF من خيارات جهازك.</p><div class="actions"><button id="elhami-export-print">طباعة / حفظ PDF</button><button class="secondary" id="elhami-export-share">مشاركة هذا الملف</button><button class="quiet" id="elhami-export-html">تنزيل الملف المنسّق</button><button class="quiet" id="elhami-export-text">تنزيل النص الكامل</button></div><iframe id="elhami-export-preview" class="export-preview" title="معاينة ملف إلهامي" sandbox="allow-same-origin allow-modals"></iframe><p id="elhami-export-status" role="status" class="small muted"></p></div>`);const frame=document.getElementById('elhami-export-preview');frame.srcdoc=html;const statusNode=document.getElementById('elhami-export-status'),shareButton=document.getElementById('elhami-export-share');let sharing=false;const current=()=>statusNode.isConnected&&document.getElementById('elhami-export-status')===statusNode;const status=t=>{if(current())statusNode.textContent=t;};document.getElementById('elhami-export-print').onclick=()=>{try{frame.contentWindow.focus();frame.contentWindow.print();status('اختر حفظ PDF في نافذة الطباعة. لم يُرسل الملف لأحد.');}catch{status('تعذر فتح الطباعة داخل المتصفح. نزّل الملف المنسّق وافتحه ثم اطبعه من جهازك.');}};document.getElementById('elhami-export-html').onclick=()=>download(blob,'elhami-draft.html');document.getElementById('elhami-export-text').onclick=()=>download(new Blob([buildText(x)],{type:'text/plain;charset=utf-8'}),'elhami-draft.txt');shareButton.onclick=async()=>{if(sharing||!current())return;sharing=true;shareButton.disabled=true;try{const file=new File([blob],'elhami-draft.html',{type:'text/html'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:x.title});status('أُغلقت نافذة المشاركة. لا يستطيع الموقع تأكيد تسلّم المستلم.');}else{status('مشاركة الملفات غير مدعومة هنا. نزّل الملف المنسّق ثم أرسله من تطبيق الملفات.');}}catch(e){status(e?.name==='AbortError'?'أُلغيت المشاركة.':'تعذرت المشاركة. يمكنك تنزيل الملف وإرساله بنفسك.');}finally{sharing=false;if(current())shareButton.disabled=false;}};}
window.ElhamiDraftExport={open,selectExport,buildHTML,buildText};
})();
